import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CWWEQfK7.js";const h=JSON.parse('{"title":"术语表","description":"用简短定义区分 Ershu 中容易混淆的项目、运行、索引、认证和配置概念。","frontmatter":{"page_id":"reference-glossary","title":"术语表","description":"用简短定义区分 Ershu 中容易混淆的项目、运行、索引、认证和配置概念。"},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1786627803000}'),o={name:"reference/glossary.md"};function s(n,t,i,l,c,_){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>项目（Project）</td><td>一组共同分析、授权和查询的仓库，是 Ershu 的主要访问边界。</td></tr><tr><td>仓库（Repository）</td><td>项目中的一个 GitHub、GitLab 或受信任本地代码源，记录目标分支、凭据和更新策略。</td></tr><tr><td>全项目分析（<code>full_project</code>）</td><td>覆盖项目所有有效仓库的分析。第一次成功结果会建立后续增量分析所需的基线。</td></tr><tr><td>增量分析</td><td>在已有全项目基线上处理新提交，并更新项目级结果的分析。</td></tr><tr><td>运行（Run）</td><td>一次分析请求及其完整状态，包括范围、阶段、事件、检查点、用量和结果。</td></tr><tr><td>队列项（Queue item）</td><td>Worker 可以领取和续租的持久任务记录。API 创建运行不等于任务已经执行。</td></tr><tr><td>分析快照</td><td>API 保存的当前运行视图。刷新或实时连接中断后，前端可以重新读取它。</td></tr><tr><td>仓库事实</td><td>从目标提交确定性提取的树、文件、语言和结构信息，不等同于模型生成的解释。</td></tr><tr><td>代码索引</td><td>用于列出和定位代码实体、符号与来源位置的结构化结果。</td></tr><tr><td>知识关系</td><td>文件、符号和其他代码实体之间的关系，用于关系图和上下文查询。</td></tr><tr><td>词法搜索</td><td>按名称和文本匹配已经建立的索引，不依赖向量相似度。</td></tr><tr><td>语义搜索</td><td>用嵌入向量按含义查找内容，需要 Milvus 和嵌入设置。</td></tr><tr><td>混合搜索</td><td>组合词法与语义结果；支持的语义失败可以被明确报告为词法回退。</td></tr><tr><td>模型通道</td><td>管理员保存并启用的一组模型提供方、模型和凭据设置，供文档生成与问答使用。</td></tr><tr><td>MCP</td><td>模型上下文协议。Ershu 通过它为开发智能体提供项目范围的只读查询工具。</td></tr><tr><td>MCP 密钥</td><td>带项目范围的 Bearer 凭据。服务端保存的是带版本的 HMAC-SHA256 摘要，不是明文密钥。</td></tr><tr><td>OPAQUE</td><td>网页密码注册与登录使用的协议。服务端保存 OPAQUE password file，而不是可直接还原的密码。</td></tr><tr><td>运行时设置</td><td>可以由管理员在线修改，并保存到数据库的配置。其数据库值可覆盖同名启动值。</td></tr><tr><td>启动设置</td><td>进程从环境读取的配置。部分值用于提供运行时设置默认值，安全与连接类设置通常只在启动时生效。</td></tr><tr><td>Core</td><td>安装进 API、Worker 与 MCP 的共享 Python 包，负责共同数据和规则；不是独立网络服务。</td></tr><tr><td>来源引用</td><td>文档、搜索或问答结果指向仓库、提交、路径和位置的信息，用于回到当前源码核对。</td></tr></tbody></table><p>术语随数据模型与公开契约更新。需要精确字段时，应继续查看对应配置或开发页面，而不是从本表推断未说明行为。</p>',3)])])}const u=d(o,[["render",s]]);export{h as __pageData,u as default};
